import{_ as r,o,c as t,a5 as a}from"./chunks/framework.CXroN2RO.js";const s="/study/images/tools/file-io-tracing.svg",m=JSON.parse('{"title":"WindowsのファイルI/OをProcmonとWPRで追う","description":"","frontmatter":{"title":"WindowsのファイルI/OをProcmonとWPRで追う","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"Procmonのファイル操作と、WPAのFile I/O・Disk Usageを使い分ける。時刻・パス・プロセスを手掛かりに、アプリの読み取りと下位のディスク要求の関係を調べる。","aliases":["Process Monitor","Procmon","WPR","WPA","ETW","ETL","File I/O","Disk Usage","Disk Service Time","I/Oトレース"],"verification":"MicrosoftのSysinternals、Windows Performance Toolkit、ETWイベント仕様に照合（2026-11-06）"}},"headers":[],"relativePath":"tools/windows/file-io-tracing.md","filePath":"tools/windows/file-io-tracing.md"}'),i={name:"tools/windows/file-io-tracing.md"};function n(d,e,c,l,f,p){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="windowsのファイルi-oをprocmonとwprで追う" tabindex="-1">WindowsのファイルI/OをProcmonとWPRで追う <a class="header-anchor" href="#windowsのファイルi-oをprocmonとwprで追う" aria-label="Permalink to &quot;WindowsのファイルI/OをProcmonとWPRで追う&quot;">​</a></h1><p>ゲームがアセットを読み込むとき、ファイルを開けたか、どれだけのデータが届いたか、ストレージへの要求が発生したかは、それぞれ別の箇所で確認します。Process Monitor（Procmon）では、ファイルシステムの操作をパス・結果・スレッドスタックと一緒に調べられます。Windows Performance Recorder（WPR）で記録してWindows Performance Analyzer（WPA）で開くと、ファイル操作と下位のディスク要求を同じ時間軸で見比べられます。<a href="https://learn.microsoft.com/en-us/sysinternals/downloads/procmon" target="_blank" rel="noreferrer">MicrosoftのProcmon資料</a> · <a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/support-tools/support-tools-xperf-wpa-wpr" target="_blank" rel="noreferrer">WPRとWPAの概要</a></p><figure class="study-figure"><img src="'+s+'" alt="同じファイル範囲を2回読む架空の時間軸。アプリの要求AとBに対応する2件のファイル操作がある。Aの間にはディスク読み取りが1件あり、BはOSに残ったデータで完了して下位の読み取りを発行しない。" width="760" height="410" loading="lazy"><figcaption>同じ範囲を2回読む概念例です。Aで取得したデータがOSに残っていれば、Bのファイル操作はディスクへの新しい読み取りを伴わずに終わります。<a href="/study/images/tools/file-io-tracing.svg" target="_blank" rel="noopener noreferrer">観測位置の図を拡大</a></figcaption></figure><h2 id="procmonでファイル操作と結果を見る" tabindex="-1">Procmonでファイル操作と結果を見る <a class="header-anchor" href="#procmonでファイル操作と結果を見る" aria-label="Permalink to &quot;Procmonでファイル操作と結果を見る&quot;">​</a></h2><p>対象のプロセス名またはPID、ファイルのパス、操作の種類で絞り込みます。<code>CreateFile</code>の行で、パスを開く処理の結果や要求されたアクセス権を調べます。<code>ReadFile</code>の行では、ファイル先頭からのオフセットと読み取り長などを確認します。操作を開いて<code>Stack</code>を表示すると、記録された呼び出し元をたどれます。シンボルが解決できると、どのライブラリやアセットローダーから来た操作かを絞りやすくなります。<a href="https://learn.microsoft.com/en-us/sysinternals/downloads/procmon" target="_blank" rel="noreferrer">MicrosoftのProcmon資料</a> · <a href="/study/os/file-read-journey.html">ファイルを開いて読むまで</a></p><p>たとえば、ロードの失敗なら<code>CreateFile</code>で<code>NAME NOT FOUND</code>や<code>ACCESS DENIED</code>が出たパスを確認します。候補の場所を順に探すアプリでは、途中の候補が見つからなくても、後続のパスで開けることがあります。対象機能が最終的にどのパスを開いたかまで追います。<code>ReadFile</code>の結果が<code>SUCCESS</code>であれば、まずファイルシステムで読み取りが成功した行として扱います。そのデータの取得経路は、OSのファイルキャッシュとディスク側の記録を照合して調べます。<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-client/shell-experience/troubleshoot-apps-start-failure-use-process-monitor" target="_blank" rel="noreferrer">Microsoftのアクセス拒否の調査例</a> · <a href="https://learn.microsoft.com/en-us/windows/msix/psf/psf-current-working-directory" target="_blank" rel="noreferrer">ファイルが見つからない場合の調査例</a> · <a href="/study/os/windows-file-cache.html">Windowsのファイルキャッシュ</a></p><h2 id="wprで記録し、wpaで層を並べる" tabindex="-1">WPRで記録し、WPAで層を並べる <a class="header-anchor" href="#wprで記録し、wpaで層を並べる" aria-label="Permalink to &quot;WPRで記録し、WPAで層を並べる&quot;">​</a></h2><p>**ETW（Event Tracing for Windows）**は、OSやアプリなどが出すイベントを記録する仕組みです。WPRではプロファイルを選んで対象のイベントを記録し、<code>.etl</code>に保存します。ファイル操作とディスク要求を調べるときは、<code>File I/O activity</code>と<code>Disk I/O activity</code>を選び、同じ実行の区間を記録します。WPAで開き、<code>Storage</code>の<code>File I/O</code>と<code>Disk Usage</code>を表示します。<a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/sessions" target="_blank" rel="noreferrer">WPRのセッションとバッファ</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/recording-for-resource-based-analysis" target="_blank" rel="noreferrer">WPRの記録プロファイル</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/list-of-wpa-graphs" target="_blank" rel="noreferrer">WPAのグラフ一覧</a></p><table tabindex="0"><thead><tr><th>観測する場所</th><th>主な手掛かり</th><th>調べたいこと</th></tr></thead><tbody><tr><td>アプリのログ</td><td>要求ID、PID、パス、ファイル内オフセット、要求長、実際のバイト数</td><td>どのアセット処理が読み取りを出し、どの段階で結果を受け取ったか</td></tr><tr><td>Procmon</td><td>操作、パス、結果、詳細、スレッドスタック</td><td>開けなかったファイルや、意図せず繰り返したファイル操作はどれか</td></tr><tr><td>WPAの<code>File I/O</code></td><td>プロセス、スレッド、ファイル名、種類、サイズ、時間</td><td>指定区間に、どのファイル操作がどれくらい発生したか</td></tr><tr><td>WPAの<code>Disk Usage</code></td><td>ディスク、種類、サイズ、パス、サービス時間</td><td>Windowsのストレージ側で、どの要求が処理されたか</td></tr></tbody></table><h2 id="同じ時間軸で対応を絞る" tabindex="-1">同じ時間軸で対応を絞る <a class="header-anchor" href="#同じ時間軸で対応を絞る" aria-label="Permalink to &quot;同じ時間軸で対応を絞る&quot;">​</a></h2><ol><li>アプリがログに出したパスとPIDを使い、<code>File I/O</code>で対象のプロセスと操作を絞ります。対象の読み取りが集まる区間を選び、<code>Disk Usage</code>も同じ区間に拡大します。</li><li><code>Disk Usage</code>では操作の種類、パス、サイズ、時刻を照合します。対象アプリのPIDの行に加えて、<code>System</code>などの行も確認します。先読みや遅延書き込みは、元のアプリの呼び出しと別のスレッドや時刻に処理される場合があります。名前を特定できなかった行も含めて確認します。<a href="https://learn.microsoft.com/en-us/windows-server/administration/performance-tuning/role/file-server/smb-file-server" target="_blank" rel="noreferrer">Microsoftのキャッシュマネージャーとワーカーの解説</a></li><li>一つのファイル操作に対応するディスク要求の数は、キャッシュやファイルの配置に応じて変わります。たとえば小さな読み取りに対して先読みで広い範囲が取得され、後の読み取りもそのデータで済むことがあります。ファイルイベントのオフセットは<strong>ファイル先頭</strong>、ディスクイベントのオフセットは<strong>ディスク先頭</strong>を基準にします。両方の数字をそのまま照合すると、別の位置を比べることになります。<a href="https://learn.microsoft.com/en-us/windows/win32/etw/fileio-readwrite" target="_blank" rel="noreferrer">ETWのFileIo_ReadWrite</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/etw/diskio-typegroup1" target="_blank" rel="noreferrer">ETWのDiskIo_TypeGroup1</a> · <a href="/study/os/windows-file-cache.html">Windowsのファイルキャッシュ</a></li></ol><p>時刻を突き合わせる場合は基準をそろえます。たとえばアプリの開始からの経過時間とWPAのトレース開始からの経過時間を使う場合、アプリの起動など、両方で識別できる出来事を基点にします。短い処理が並ぶ区間ではパス・種類・サイズも使って候補を絞ります。</p><h2 id="時間が長い場所を切り分ける" tabindex="-1">時間が長い場所を切り分ける <a class="header-anchor" href="#時間が長い場所を切り分ける" aria-label="Permalink to &quot;時間が長い場所を切り分ける&quot;">​</a></h2><p><code>Disk Usage</code>の<code>IO Time</code>と<code>Disk Service Time</code>を見比べると、Windowsでディスク要求を処理する過程のうち、待ち行列を含む時間とサービス時間を区別できます。ファイルを読み始めてからゲームが使えるまでの時間には、これに加えて、ファイルシステムの処理、完了通知をワーカーが取り出すまでの時間、展開や解析などが含まれます。アプリでも発行と回収の時刻を記録し、非同期読み取りの時間と、その結果を使う時間を分けます。<a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/optimizing-performance-and-responsiveness-exercise-2#step-5-analyze-process-disk-usage" target="_blank" rel="noreferrer">WPAでディスク利用を分析する例</a> · <a href="/study/os/io-completion-ports.html">I/O完了ポート</a> · <a href="/study/game/asset-loading.html">実行時のアセットロード</a></p><p>ディスク要求が見えた場合、確認できるのはWindowsから見たストレージI/Oです。たとえばSSDが内部キャッシュで応答したか、フラッシュメモリから読んだかを知るには、デバイス側の観測が必要です。対応するディスク読み取りが見えない場合は、対象のプロファイル・期間・フィルターを確かめ、イベントの欠落がないか確認した上で、OSのキャッシュで処理された可能性を調べます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-buffering" target="_blank" rel="noreferrer">Microsoftのファイルバッファリング資料</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/etw/diskio-typegroup1" target="_blank" rel="noreferrer">ETWのDiskIo_TypeGroup1</a></p><h2 id="比較できる記録を取る" tabindex="-1">比較できる記録を取る <a class="header-anchor" href="#比較できる記録を取る" aria-label="Permalink to &quot;比較できる記録を取る&quot;">​</a></h2><p>対象の操作を短く再現し、使うプロファイルを絞ります。ファイルへ記録する設定では、トレースファイルの書き込み自体もディスク使用量に加わります。メモリへ記録する設定では、長く続けると古いイベントが上書きされます。記録時に<code>Events dropped</code>が増えた場合は、対象区間を短くしたりプロファイルを減らしたりして、記録を取り直します。<a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/logging-mode" target="_blank" rel="noreferrer">WPRの記録モード</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/wpr-how-to-topics#avoid-lost-events" target="_blank" rel="noreferrer">WPRでイベント欠落を調べる方法</a></p><p>記録にはファイルのパス、プロセス名やコマンドライン、環境によってはユーザー名なども含まれます。結果を教材やチケットに載せるときは、試験用の名前で再現し、必要な行を抜き出して共有します。Procmonの通常の表示フィルターは、元の記録にあるイベントを保持します。<a href="https://learn.microsoft.com/en-us/sysinternals/downloads/procmon" target="_blank" rel="noreferrer">MicrosoftのProcmon資料</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/wpr-how-to-topics#stop-a-recording" target="_blank" rel="noreferrer">WPRで記録に含まれる情報</a></p><p>手元では、同じファイルに対する読み取りを繰り返し、アプリの出力とツールの記録を比べられます。<a href="/study/practice/io/file-io-trace-observation.html">ファイル読み取りをトレースする実践</a></p>',19)])])}const w=r(i,[["render",n]]);export{m as __pageData,w as default};
